/**
 * @summary Append a corrected typed fact revision.
 */
export const factMaintenanceControllerCorrectPathFactRecordIdRegExp =
  new RegExp(
    '^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$',
  )

export const FactMaintenanceControllerCorrectParams = zod.strictObject({
  factRecordId: zod
    .string()
    .regex(factMaintenanceControllerCorrectPathFactRecordIdRegExp),
})

export const factMaintenanceControllerCorrectBodyCommandIdRegExp = new RegExp(
  '^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$',
)
export const factMaintenanceControllerCorrectBodyExpectedRevisionRegExp =
  new RegExp('^[1-9][0-9]*$')
export const factMaintenanceControllerCorrectBodyReasonMax = 2000

export const factMaintenanceControllerCorrectBodyReasonRegExp = new RegExp(
  '^[\\s\\S]*\\S[\\s\\S]*$',
)
export const factMaintenanceControllerCorrectBodyValueTwoValueRegExp =
  new RegExp('^(?:0|[1-9][0-9]*)(?:\\.[0-9]+)?$')
export const factMaintenanceControllerCorrectBodyValueThreeValueRegExp =
  new RegExp('^(?:[01][0-9]|2[0-3]):[0-5][0-9]$')
export const factMaintenanceControllerCorrectBodyValueFourValueMin =
  -9007199254740991
export const factMaintenanceControllerCorrectBodyValueFourValueMax = 9007199254740991

export const factMaintenanceControllerCorrectBodyValueSevenValueRegExp =
  new RegExp('^(?:0|[1-9][0-9]*)(?:\\.[0-9]+)?$')

export const FactMaintenanceControllerCorrectBody = zod.strictObject({
  commandId: zod
    .string()
    .regex(factMaintenanceControllerCorrectBodyCommandIdRegExp),
  expectedRevision: zod
    .string()
    .regex(factMaintenanceControllerCorrectBodyExpectedRevisionRegExp),
  reason: zod
    .string()
    .min(1)
    .max(factMaintenanceControllerCorrectBodyReasonMax)
    .regex(factMaintenanceControllerCorrectBodyReasonRegExp),
  value: zod.union([
    zod.strictObject({
      kind: zod.enum(['boolean']),
      result: zod.enum(['done', 'not_done']),
    }),
    zod.strictObject({
      kind: zod.enum(['quantity']),
      value: zod
        .string()
        .regex(factMaintenanceControllerCorrectBodyValueTwoValueRegExp),
    }),
    zod.strictObject({
      kind: zod.enum(['actual_time']),
      value: zod
        .string()
        .regex(factMaintenanceControllerCorrectBodyValueThreeValueRegExp),
    }),
    zod.strictObject({
      kind: zod.enum(['rating']),
      value: zod
        .int()
        .min(factMaintenanceControllerCorrectBodyValueFourValueMin)
        .max(factMaintenanceControllerCorrectBodyValueFourValueMax),
    }),
    zod.strictObject({
      kind: zod.enum(['text']),
      result: zod.enum(['done', 'not_done']),
      text: zod.string().min(1),
    }),
    zod.strictObject({
      kind: zod.enum(['checklist_item']),
      state: zod.enum(['done', 'not_done']),
    }),
    zod.strictObject({
      kind: zod.enum(['or_variant']),
      value: zod
        .string()
        .regex(factMaintenanceControllerCorrectBodyValueSevenValueRegExp),
    }),
  ]),
})

